INSERT INTO topics (title, duration, level, tag, content_intro, content_section_title, content_section_text, content_code, content_tip, content_warning, order_index) VALUES
(
    'Алгоритмы и их свойства', '10 мин', 'Базовый', 'Тема 1',
    'Алгоритм — это конечная последовательность чётко определённых инструкций для решения задачи. Ключевые свойства: дискретность, детерминированность, конечность и результативность.',
    'Ключевые свойства алгоритма',
    'Каждый алгоритм должен обладать следующими свойствами: он должен быть конечным (завершаться за конечное число шагов), определённым (каждый шаг точно определён), иметь входные и выходные данные, и быть эффективным (каждый шаг выполним).',
    E'# Пример простого алгоритма поиска максимума\ndef найти_максимум(список):\n    максимум = список[0]\n    for элемент in список:\n        if элемент > максимум:\n            максимум = элемент\n    return максимум\n\n# Использование\nчисла = [3, 7, 1, 9, 4]\nprint(найти_максимум(числа))  # 9',
    'Начните урок с бытового примера: рецепт блюда — это тоже алгоритм. Ученики сразу понимают концепцию.',
    'Ученики путают алгоритм с программой. Подчеркните: алгоритм не зависит от языка программирования — он про логику.',
    1
),
(
    'Типы данных', '8 мин', 'Базовый', 'Тема 2',
    'Тип данных определяет множество допустимых значений и операций над ними. В Python основные типы: int, float, str, bool, list, dict.',
    'Основные типы данных в Python',
    'Python является языком с динамической типизацией — тип переменной определяется автоматически при присваивании значения. Это удобно для начинающих, но требует понимания преобразований типов.',
    E'# Основные типы данных Python\nцелое = 42           # int\nдробное = 3.14       # float\nстрока = "Привет"    # str\nбулево = True        # bool\n\n# Преобразование типов\nчисло_строкой = str(целое)    # "42"\nстрока_числом = int("100")    # 100\n\nprint(type(целое))   # <class ''int''>',
    'Используйте функцию type() для демонстрации — ученики видят тип прямо в консоли. Это наглядно.',
    'Частая ошибка: сложение числа и строки. Например, "5" + 5 вызовет TypeError. Покажите это явно.',
    2
),
(
    'Условия и циклы', '15 мин', 'Базовый', 'Тема 3',
    'Условные операторы (if/elif/else) и циклы (for/while) — основа управления потоком выполнения программы.',
    'Управляющие конструкции',
    'Условные операторы позволяют программе принимать решения, а циклы — повторять действия. Вместе они образуют основу любой нетривиальной программы.',
    E'# Условия\nоценка = 85\n\nif оценка >= 90:\n    print("Отлично")\nelif оценка >= 70:\n    print("Хорошо")\nelse:\n    print("Нужно поработать")\n\n# Цикл for\nfor i in range(1, 6):\n    print(f"Шаг {i}")\n\n# Цикл while\nсчётчик = 0\nwhile счётчик < 3:\n    print(f"Итерация {счётчик}")\n    счётчик += 1',
    'Начните с блок-схемы на доске. Визуализация if/else через блок-схему резко снижает количество ошибок у учеников.',
    'Бесконечный цикл while — классическая ошибка. Всегда показывайте пример с забытым инкрементом счётчика.',
    3
),
(
    'Функции', '12 мин', 'Средний', 'Тема 4',
    'Функция — именованный блок кода, который можно вызывать многократно. Принципы: DRY (Don''t Repeat Yourself) и единственная ответственность.',
    'Определение и вызов функций',
    'Функции позволяют разбить программу на логические блоки, каждый из которых решает одну конкретную задачу. Это упрощает чтение, тестирование и отладку кода.',
    E'# Определение функции\ndef приветствие(имя, возраст=18):\n    """Функция приветствия с параметрами"""\n    return f"Привет, {имя}! Тебе {возраст} лет."\n\n# Вызов\nprint(приветствие("Алия"))         # возраст по умолчанию\nprint(приветствие("Данияр", 20))   # свой возраст\n\n# Функция с несколькими возвращаемыми значениями\ndef мин_макс(список):\n    return min(список), max(список)\n\nминимум, максимум = мин_макс([3, 1, 7, 2])',
    'Объясняйте функции через аналогию с кнопкой: нажал (вызвал) — получил результат. Параметры — это настройки кнопки.',
    'Ученики часто путают return и print. Покажите разницу: print выводит на экран, return передаёт значение обратно.',
    4
),
(
    'Массивы и списки', '14 мин', 'Средний', 'Тема 5',
    'Список (list) в Python — упорядоченная изменяемая коллекция элементов. Один из самых используемых типов данных.',
    'Работа со списками',
    'Списки позволяют хранить несколько значений в одной переменной. Они поддерживают индексацию, срезы, и множество встроенных методов для удобной работы с данными.',
    E'# Создание и операции со списком\nстуденты = ["Алия", "Данияр", "Зарина"]\n\n# Доступ по индексу\nprint(студенты[0])    # Алия\nprint(студенты[-1])   # Зарина (с конца)\n\n# Методы списка\nстуденты.append("Бекзат")   # добавить\nстуденты.remove("Данияр")   # удалить\nстуденты.sort()              # сортировать\n\n# Срезы\nпервые_двое = студенты[0:2]\n\n# Перебор\nfor студент in студенты:\n    print(f"Студент: {студент}")',
    'Визуализируйте список как шкафчики с номерами. Индекс — это номер шкафчика. Нумерация с нуля — важный момент.',
    'IndexError при обращении к несуществующему индексу — частая ошибка. Отработайте её специально на занятии.',
    5
),
(
    'ООП — основы', '20 мин', 'Продвинутый', 'Тема 6',
    'Объектно-ориентированное программирование — парадигма, основанная на концепции объектов, содержащих данные и методы.',
    'Классы и объекты',
    'Класс — это шаблон для создания объектов. Объект — конкретный экземпляр класса. Три столпа ООП: инкапсуляция, наследование, полиморфизм.',
    E'# Определение класса\nclass Студент:\n    def __init__(self, имя, оценка):\n        self.имя = имя\n        self.оценка = оценка\n    \n    def статус(self):\n        if self.оценка >= 70:\n            return f"{self.имя}: сдал ✓"\n        return f"{self.имя}: не сдал ✗"\n    \n    def __str__(self):\n        return f"Студент({self.имя}, {self.оценка})"\n\n# Создание объектов\nалия = Студент("Алия", 88)\nданияр = Студент("Данияр", 65)\n\nprint(алия.статус())    # Алия: сдал ✓\nprint(данияр.статус())  # Данияр: сдал ✓',
    'Объясняйте класс через форму для печенья: форма — это класс, каждое печенье — объект. Все печенья одинаковой формы, но могут отличаться начинкой.',
    'self — самая частая точка непонимания. Потратьте отдельное время чтобы объяснить зачем он нужен.',
    6
),
(
    'Рекурсия', '18 мин', 'Продвинутый', 'Тема 7',
    'Рекурсия — это когда функция вызывает сама себя. Каждая рекурсивная функция должна иметь базовый случай (условие остановки).',
    'Принцип рекурсии',
    'Рекурсивные решения часто элегантнее итеративных, но требуют больше памяти из-за стека вызовов. Важно всегда определять базовый случай, иначе возникнет бесконечная рекурсия.',
    E'# Классический пример: факториал\ndef факториал(n):\n    # Базовый случай\n    if n == 0 or n == 1:\n        return 1\n    # Рекурсивный вызов\n    return n * факториал(n - 1)\n\nprint(факториал(5))  # 120\n# 5 * 4 * 3 * 2 * 1 = 120\n\n# Числа Фибоначчи\ndef фибоначчи(n):\n    if n <= 1:\n        return n\n    return фибоначчи(n-1) + фибоначчи(n-2)\n\nfor i in range(8):\n    print(фибоначчи(i), end=" ")  # 0 1 1 2 3 5 8 13',
    'Нарисуйте дерево вызовов на доске для факториала(4). Визуализация стека вызовов — лучший способ объяснить рекурсию.',
    'Без базового случая — бесконечная рекурсия и RecursionError. Всегда начинайте объяснение с условия остановки.',
    7
),
(
    'Алгоритмы сортировки', '22 мин', 'Продвинутый', 'Тема 8',
    'Сортировка — упорядочивание элементов по заданному критерию. Разные алгоритмы имеют разную сложность: от O(n²) до O(n log n).',
    'Сортировка пузырьком',
    'Сортировка пузырьком — простейший алгоритм для понимания. Несмотря на низкую эффективность O(n²), она идеальна для обучения принципам сортировки.',
    E'# Сортировка пузырьком\ndef пузырьковая_сортировка(список):\n    n = len(список)\n    for i in range(n):\n        for j in range(0, n - i - 1):\n            if список[j] > список[j + 1]:\n                # Меняем местами\n                список[j], список[j+1] = список[j+1], список[j]\n    return список\n\nчисла = [64, 34, 25, 12, 22, 11, 90]\nprint(пузырьковая_сортировка(числа))\n# [11, 12, 22, 25, 34, 64, 90]\n\n# Встроенная сортировка Python (быстрее)\nчисла.sort()           # изменяет список\nsorted_list = sorted(числа)  # создаёт новый',
    'Есть отличная визуализация на сайте visualgo.net — покажите её в классе. Ученики видят каждый шаг алгоритма в реальном времени.',
    'Не нужно заставлять учеников писать сортировку пузырьком для реальных задач — объясните что есть sort() и sorted(). Цель — понять принцип.',
    8
);
